from z3 import *
import itertools

# Parameters
G = 18  # golfers
W = 7   # weeks
S = 6   # groups per week
K = 3   # group size

# Variables: x[w][g][p] = 1 if golfer p is in group g in week w
x = [[[Bool(f'x_{w}_{g}_{p}') for p in range(G)] for g in range(S)] for w in range(W)]

solver = Solver()

# Each golfer in exactly one group per week
for w in range(W):
    for p in range(G):
        solver.add(Sum([x[w][g][p] for g in range(S)]) == 1)

# Each group has exactly K golfers
for w in range(W):
    for g in range(S):
        solver.add(Sum([x[w][g][p] for p in range(G)]) == K)

# No pair of golfers in same group more than once
for p1 in range(G):
    for p2 in range(p1+1, G):
        pair_weeks = []
        for w in range(W):
            for g in range(S):
                pair_weeks.append(And(x[w][g][p1], x[w][g][p2]))
        solver.add(Sum([If(pw, 1, 0) for pw in pair_weeks]) <= 1)

print("Solving...")
result = solver.check()
print(result)

if result == sat:
    m = solver.model()
    # Build solution: for each week w and golfer p, find which group
    solution = [0] * (W * G)
    for w in range(W):
        for p in range(G):
            for g in range(S):
                if is_true(m.eval(x[w][g][p])):
                    solution[w * G + p] = g
                    break
    print(solution)
    print(len(solution))

    # Verify
    # Check each week: each group has exactly 3
    for w in range(W):
        groups = [[] for _ in range(S)]
        for p in range(G):
            g = solution[w * G + p]
            groups[g].append(p)
        for g in range(S):
            assert len(groups[g]) == 3, f"Week {w}, group {g} has {len(groups[g])} members"

    # Check no pair appears twice
    from collections import defaultdict
    pair_weeks = defaultdict(list)
    for w in range(W):
        groups = [[] for _ in range(S)]
        for p in range(G):
            g = solution[w * G + p]
            groups[g].append(p)
        for g in range(S):
            for i in range(K):
                for j in range(i+1, K):
                    p1, p2 = groups[g][i], groups[g][j]
                    pair = (min(p1, p2), max(p1, p2))
                    pair_weeks[pair].append(w)
    for pair, weeks in pair_weeks.items():
        if len(weeks) > 1:
            print(f"Pair {pair} appears in weeks {weeks}")
    print("Verification passed!")

